-- Spoken-only variants, never additional /me text.
local _, addon = ...
local texts = addon.localeData.frFR.generalTexts
texts.COMMEND = { gruppe = { "Tes efforts méritent des éloges devant tous.", "Tous les héros n'ont pas besoin d'une médaille." }, ziel = { "%s: Tous les héros n'ont pas besoin d'une médaille.", "%s: Tes efforts méritent des éloges devant tous." } }
texts.DRINK = { gruppe = { "Aux bons amis et aux retours sans danger !", "Cette chope n'a pas besoin de durer jusqu'à demain." }, ziel = { "%s: Cette chope n'a pas besoin de durer jusqu'à demain.", "%s: Aux bons amis et aux retours sans danger !" } }
texts.GIGGLE = { gruppe = { "Je voulais rester sérieux. Vraiment.", "Le fou rire a été plus fort que ma volonté." }, ziel = { "%s: Le fou rire a été plus fort que ma volonté.", "%s: Je voulais rester sérieux. Vraiment." } }
texts.PEON = { gruppe = { "Travail, travail. Il n'y a donc jamais de fin ?", "Qui a encore distribué du travail ?" }, ziel = { "%s: Qui a encore distribué du travail ?", "%s: Travail, travail. Il n'y a donc jamais de fin ?" } }
texts.SHINDIG = { gruppe = { "Ce soir on fait la fête jusqu'à épuiser les bottes !", "Que tout le camp entende la musique." }, ziel = { "%s: Que tout le camp entende la musique.", "%s: Ce soir on fait la fête jusqu'à épuiser les bottes !" } }
texts.SOB = { gruppe = { "Parfois le souvenir fait tout simplement mal.", "J'ai besoin d'un moment de silence." }, ziel = { "%s: J'ai besoin d'un moment de silence.", "%s: Parfois le souvenir fait tout simplement mal." } }
texts.VICTORY = { gruppe = { "Ce fut une victoire durement acquise !", "N'oublions pas ceux qui se tenaient à nos côtés." }, ziel = { "%s: N'oublions pas ceux qui se tenaient à nos côtés.", "%s: Ce fut une victoire durement acquise !" } }
texts.WEEP = { gruppe = { "Certains adieux demandent tant de larmes.", "Peut-être que demain le monde sera plus doux." }, ziel = { "%s: Peut-être que demain le monde sera plus doux.", "%s: Certains adieux demandent tant de larmes." } }
texts.WELCOME = { gruppe = { "Il reste de la place près du feu.", "Entre. La bonne compagnie est toujours bienvenue." }, ziel = { "%s: Entre. La bonne compagnie est toujours bienvenue.", "%s: Il reste de la place près du feu." } }
texts.YES = { gruppe = { "Oui, c'est exactement ce que nous allons faire !", "Une réponse claire évite bien des détours." }, ziel = { "%s: Une réponse claire évite bien des détours.", "%s: Oui, c'est exactement ce que nous allons faire !" } }
texts.CAT = { gruppe = { "Miaou. Il faut bien se faire comprendre.", "Un peu de sagesse féline ne fait jamais de mal." }, ziel = { "%s: Un peu de sagesse féline ne fait jamais de mal.", "%s: Miaou. Il faut bien se faire comprendre." } }
texts.CATTY = { gruppe = { "Un mot gentil serait apparemment trop facile.", "Il fallait vraiment lancer cette remarque griffue." }, ziel = { "%s: Il fallait vraiment lancer cette remarque griffue.", "%s: Un mot gentil serait apparemment trop facile." } }
texts.CUDDLE = { gruppe = { "Certains jours demandent simplement un peu de tendresse.", "Un instant de calme peut valoir plus que l'or." }, ziel = { "%s: Un instant de calme peut valoir plus que l'or.", "%s: Certains jours demandent simplement un peu de tendresse." } }
texts.FART = { gruppe = { "Pardon, une brise totalement imprévue.", "Je ne peux pas vraiment accuser le vent." }, ziel = { "%s: Je ne peux pas vraiment accuser le vent.", "%s: Pardon, une brise totalement imprévue." } }
texts.PURR = { gruppe = { "La satisfaction n'a pas toujours besoin de mots.", "Je pourrais rester ici bien longtemps." }, ziel = { "%s: Je pourrais rester ici bien longtemps.", "%s: La satisfaction n'a pas toujours besoin de mots." } }
texts.VOLUNTEER = { gruppe = { "Je m'en charge. Qui vient avec moi ?", "Si quelqu'un doit commencer, autant que ce soit moi." }, ziel = { "%s: Si quelqu'un doit commencer, autant que ce soit moi.", "%s: Je m'en charge. Qui vient avec moi ?" } }
texts.WHINE = { gruppe = { "Pourquoi faut-il toujours que cela m'arrive ?", "J'espérais une mission plus simple." }, ziel = { "%s: J'espérais une mission plus simple.", "%s: Pourquoi faut-il toujours que cela m'arrive ?" } }
texts.WHISTLE = { gruppe = { "Une mélodie joyeuse aide pendant les longs voyages.", "Certaines mélodies viennent toutes seules en chemin." }, ziel = { "%s: Certaines mélodies viennent toutes seules en chemin.", "%s: Une mélodie joyeuse aide pendant les longs voyages." } }
texts.WICKED = { gruppe = { "Voilà une idée délicieusement audacieuse.", "Je devrais probablement avoir mauvaise conscience." }, ziel = { "%s: Je devrais probablement avoir mauvaise conscience.", "%s: Voilà une idée délicieusement audacieuse." } }
texts.WICKEDLY = { gruppe = { "Mon plan a des angles. Très tranchants.", "Certains choix sont étonnamment amusants." }, ziel = { "%s: Certains choix sont étonnamment amusants.", "%s: Mon plan a des angles. Très tranchants." } }
texts.WORK = { gruppe = { "Une bonne journée commence par un travail accompli.", "Le travail m'appelle. Malheureusement il connaît mon nom." }, ziel = { "%s: Le travail m'appelle. Malheureusement il connaît mon nom.", "%s: Une bonne journée commence par un travail accompli." } }
texts.WRATH = { gruppe = { "Assez ! Ma clémence s'arrête ici.", "La colère sans action n'est que du bruit." }, ziel = { "%s: La colère sans action n'est que du bruit.", "%s: Assez ! Ma clémence s'arrête ici." } }
texts.YAWN = { gruppe = { "Je pourrais dormir ici pendant trois jours.", "Une pause ferait des miracles maintenant." }, ziel = { "%s: Une pause ferait des miracles maintenant.", "%s: Je pourrais dormir ici pendant trois jours." } }
texts.BURP = { gruppe = { "Le ragoût vient de faire ses adieux.", "C'était plus bruyant que prévu." }, ziel = { "%s: C'était plus bruyant que prévu.", "%s: Le ragoût vient de faire ses adieux." } }
texts.BLOOD = { gruppe = { "Il y a plus de sang que je ne voulais en voir.", "Une pause et un bandage seraient judicieux." }, ziel = { "%s: Une pause et un bandage seraient judicieux.", "%s: Il y a plus de sang que je ne voulais en voir." } }
texts.HAIL = { gruppe = { "Je salue tous ceux qui montent la garde ici.", "Honneur à ceux qui gardent la route libre." }, ziel = { "%s: Honneur à ceux qui gardent la route libre.", "%s: Je salue tous ceux qui montent la garde ici." } }
texts.RDY = { gruppe = { "Prêt ! Dis seulement quand nous commençons.", "Tout est prêt, la direction est claire." }, ziel = { "%s: Tout est prêt, la direction est claire.", "%s: Prêt ! Dis seulement quand nous commençons." } }
